mapper.select:
SELECT 
  FROM sys53_specific_menu_request
       INNER JOIN sys01_company ON sys01_company_id = sys53_company_id
       LEFT OUTER JOIN apr01_appr ON apr01_appr_id = sys53_appr_id
 WHERE sys53_company_id = #{companyId}
   AND COALESCE(sys53_state_cd, ' ')         LIKE #{stateCd}
   AND COALESCE(sys53_specific_work_cd, ' ') LIKE #{specificWorkCd}
 ORDER BY sys53_reg_date, sys53_specific_work_cd, sys53_state_cd

mapper.update:
UPDATE sys53_specific_menu_request
   SET sys53_specific_work_cd = #{req.specificWorkCd},
       sys53_appr_id          = #{req.apprId}
 WHERE sys53_specific_menu_request_id = #{req.specificMenuRequestId}
   AND sys53_company_id               = #{companyId}

mapper.select:
SELECT 
  FROM sys53_specific_menu_request
       INNER JOIN sys01_company ON sys01_company_id = sys53_company_id
       LEFT OUTER JOIN apr01_appr ON apr01_appr_id = sys53_appr_id
 WHERE 1=1
   AND COALESCE(sys53_state_cd, ' ')         LIKE #{stateCd}
   AND COALESCE(sys53_specific_work_cd, ' ') LIKE #{specificWorkCd}
   AND CAST(sys53_company_id AS VARCHAR)     LIKE #{companyId}
   AND COALESCE(apr01_status_cd, '99') = '30'
 ORDER BY sys53_reg_date, sys53_specific_work_cd, sys53_state_cd

mapper.update:
UPDATE sys53_specific_menu_request
   SET sys53_state_cd     = #{req.stateCd},
       sys53_confirm_nm   = #{req.confirmNm},
       sys53_confirm_date = #{req.confirmDate}
 WHERE sys53_specific_menu_request_id = #{req.specificMenuRequestId}

mapper.delete:
